import openpyxl

def dump(wb, label):
    print(f"########## {label} ##########")
    for ws in wb.worksheets:
        print(f"=== Sheet: {ws.title} | dims: {ws.dimensions} ===")
        for row in ws.iter_rows():
            for cell in row:
                if cell.value is not None:
                    print(f"{cell.coordinate}: {cell.value!r}")
        print()

dump(openpyxl.load_workbook("budget.xlsx", data_only=False), "FORMULAS")
dump(openpyxl.load_workbook("budget.xlsx", data_only=True), "VALUES")

import zipfile, json
from xml.etree import ElementTree as ET

NAME = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
REL = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}"

def collect_text(element):
    return "".join(child.text or "" for child in element.iter(NAME + "t"))

def parse_archive(archive_path):
    with zipfile.ZipFile(archive_path) as arc:
        entries = set(arc.namelist())
        dictionary = []
        if "xl/sharedStrings.xml" in entries:
            doc = ET.fromstring(arc.read("xl/sharedStrings.xml"))
            dictionary = [collect_text(part) for part in doc.iter(NAME + "si")]
        main = ET.fromstring(arc.read("xl/workbook.xml"))
        rels_doc = ET.fromstring(arc.read("xl/_rels/workbook.xml.rels"))
        targets = {node.get("Id"): node.get("Target") for node in rels_doc}
        report = {}
        for marker in main.iter(NAME + "sheet"):
            label = marker.get("name")
            rid = marker.get(REL + "id")
            location = targets[rid]
            if not location.startswith("xl/"):
                location = "xl/" + location
            grid = ET.fromstring(arc.read(location))
            rows = []
            for line in grid.iter(NAME + "row"):
                row_cells = []
                for slot in line.iter(NAME + "c"):
                    kind = slot.get("t")
                    value = slot.find(NAME + "v")
                    formula_node = slot.find(NAME + "f")
                    content = ""
                    if formula_node is not None:
                        content = "=" + (formula_node.text or "")
                    elif value is not None and value.text is not None:
                        content = dictionary[int(value.text)] if kind == "s" else value.text
                    elif kind == "inlineStr":
                        content = collect_text(slot)
                    if content:
                        row_cells.append([slot.get("r"), content])
                if row_cells:
                    rows.append([line.get("r"), row_cells])
            report[label] = rows
        return report

