                v = c.find('m:v', NS)
                f = c.find('m:f', NS)
                if f is not None:
                    val = '=' + (f.text or '')
                elif v is None or v.text is None:
                    val = ''
                elif t == 's':
                    val = shared[int(v.text)]
                elif t == 'inlineStr':
                    val = ''.join(x.text or '' for x in c.iter('{%s}t' % NS['m']))
                else:
                    val = v.text
                vals.append((ref, val))
            print(row.get('r'), vals)

